  d.resetCharStyle(); d.font = font; d.fontSize = size; d.applyFill = true; d.fillColor = rgb(color); d.applyStroke = false;
  d.justification = just || ParagraphJustification.CENTER_JUSTIFY; d.tracking = tracking || 0;
