    bar2.position.setValue([96 + rc2.left + rc2.width / 2, y + 47]); bar2.moveAfter(b);
    keys(bar2.scale, [t0 + f2s(5), t0 + f2s(11)], [[0, 100], [100, 100]], [[10, 10], [85, 85]]);
