    keys(root.property("ADBE Vectors Group").property("ADBE Vector Shape - Ellipse").property("ADBE Vector Ellipse Size"), [t0 + f2s(6), t0 + f2s(18)], [[10, 6], [190, 70]], [[5, 5], [80, 80]]);
    keys(r.opacity, [t0 + f2s(6), t0 + f2s(18)], [100, 0], 40);
