  var l = c.layers.add(it); l.name = name || ("Bild " + rel.replace(/.*\//, ""));
  var s = h / it.height * 100; l.position.setValue([x, y]); l.scale.setValue([s, s]);
  if (bw !== false) { var b = addFx(l, "ADBE Black&White"); }
